cd ~/.claude/projects/C--Users-Anton-L-anti-slop-design && python - <<'EOF'
import json,re
for l in open("673c0400-6614-477a-bb1f-8acf01c0c5b3.jsonl",encoding="utf-8"):
    s=l
    if re.search(r"headed|headless|vakt|synlig", s, re.I) and re.search(r"block|denied|stopp|guard|hook|vakt", s, re.I):
        d=json.loads(l); ts=d.get("timestamp","")
        for m in re.finditer(r".{0,200}(?:block|denied|stopp|guard|vakt).{0,200}", s, re.I):
            t=m.group(0)
            if re.search("headed|headless|synlig|window|fönster",t,re.I): print(ts, t[:400]); print('--')
EOF

