var CASES = {
  calyx: { key: 'calyx', el: document.getElementById('showcase-calyx'), iframe: document.getElementById('showcaseIframeCalyx'), poster: document.getElementById('showcasePosterCalyx'), anchors: SHOWCASE_DEFS.calyx.anchors, y: null, w: null, last: -1, lastStep: -1, loaded: false, pendingRow: 0, mountedAt: 0 },
  horai: { key: 'horai', el: document.getElementById('showcase-horai'), iframe: document.getElementById('showcaseIframeHorai'), poster: document.getElementById('showcasePosterHorai'), anchors: SHOWCASE_DEFS.horai.anchors, y: null, w: null, last: -1, lastStep: -1, loaded: false, pendingRow: 0, mountedAt: 0 }
