var showcaseEl = document.getElementById('showcase');
/* R7 (H13): the stage is drawn only within 1.5 viewports of the screen */
(function(){
  var spacer = document.querySelector('.showcase-pin-spacer');
  var stage = document.querySelector('.showcase-stage');
  if (!spacer || !stage) return;
  if (!('IntersectionObserver' in window)){ stage.classList.remove('is-far'); return; }
  new IntersectionObserver(function(entries){
    entries.forEach(function(e){ stage.classList.toggle('is-far', !e.isIntersecting); });
