90	| 28px | 1.75rem | 700 | 38.0016px | -1.12px | h3, a, img, h2 |
91	| 22px | 1.375rem | 400 | 35.75px | normal | summary, span, svg, path |
92	| 19.2px | 1.2rem | 400 | 30px | normal | motion-element, p |
93	| 18px | 1.125rem | 900 | 27px | normal | button, svg, path, h2 |
