    if (!glideTick && !lenis.isScrolling && performance.now() - lastScrollAt > MOUNT_QUIET_MS){
      var next = pendingMounts.shift();
      if (next) mountCase(next);
      pausePoll = pendingMounts.length ? setTimeout(poll, 150) : null;
      return;
    }
    pausePoll = setTimeout(poll, 120);
