/* R7b: a mount costs 0.36-0.63 s of main thread in one piece (parse +
   Tailwind's in-browser compile + first layout, CDP-traced), and a click
   that lands inside it waits for all of it. So a mount waits for 400 ms of
   stillness (a click within ~300 ms of reaching the picker comes first and
   finds the thread free) and never runs during a click glide (mountCase). */
var MOUNT_QUIET_MS = 400;
var lastScrollAt = 0, pendingMounts = [], pausePoll = null;
lenis.on('scroll', function(){ lastScrollAt = performance.now(); });
function mountWhenPaused(C){
  if (!C || C.iframe.getAttribute('src') || pendingMounts.indexOf(C) > -1) return;
  pendingMounts.push(C);
  if (pausePoll) return;
  (function poll(){
    if (!glideTick && !lenis.isScrolling && performance.now() - lastScrollAt > MOUNT_QUIET_MS){
      var next = pendingMounts.shift();
      if (next) mountCase(next);
      pausePoll = pendingMounts.length ? setTimeout(poll, 150) : null;
      return;
    }
    pausePoll = setTimeout(poll, 120);
  })();
}
var exempelcaseEl = document.getElementById('exempelcase');
/* R7b: both fallback images are fetched and decoded as soon as the picker
   is due, mounted or not, so a click before any mount still shows one
   without a decode inside the glide */
function warmPosters(){
  Object.keys(CASES).forEach(function(k){
    var p = CASES[k].poster;
    if (!p || p.__warm) return;
    p.__warm = new Image();
    p.__warm.src = p.getAttribute('src');
    if (p.__warm.decode) p.__warm.decode().catch(function(){});
  });
}
/* R7b: a frame outside the viewport is render-throttled, so its CSS
   background photos (all of both sites' photos) were not even requested
   until the click glide pulled it on screen; its 'load', and the layout and
   decode after it, then landed inside the glide (traced: load at +0.1 to
   +0.4 s after the click, 8.7 s after the mount). One forced layout once
   the frame's document is parsed starts those requests while it is still
   off screen. Runs in requestIdleCallback, never in a scroll callback. */
function kickFrameLayout(C){
  defer(function kick(){
    var d = null;
    try { d = C.iframe.contentDocument; } catch (e) { return; }
    if (!d || d.URL === 'about:blank' || d.readyState === 'loading'){
      if (!C.loaded && performance.now() - C.mountedAt < 8000) defer(kick);
      return;
    }
    void d.documentElement.scrollHeight;
  });
}
function mountCase(C){
  var f = C && C.iframe;
  if (!f || f.getAttribute('src')) return;
  var src = f.getAttribute('data-lazy-src');
  if (!src) return;
  /* R7b: nothing loads while a click glide runs; it waits for the landing */
  if (glideTick){ afterGlide(function(){ mountCase(C); }); return; }
  scaleShowcaseFrame();
  C.mountedAt = performance.now();
  warmPosters();
  f.setAttribute('src', src);
  f.removeAttribute('data-lazy-src');
  kickFrameLayout(C);
  /* the other case queues right away (not on this one's load, which the
     sites' hotlinked photos delay by seconds), so it too loads while the
     reader is still, before a click on it */
  if (C.key === activeCaseKey) mountWhenPaused(otherCase(C.key));
}
function otherCase(key){ return key === 'calyx' ? CASES.horai : CASES.calyx; }
var showcaseEl = document.getElementById('showcase');
/* R7 (H13): the stage is drawn only within 1.5 viewports of the screen */
(function(){
  var spacer = document.querySelector('.showcase-pin-spacer');
  var stage = document.querySelector('.showcase-stage');
  if (!spacer || !stage) return;
  if (!('IntersectionObserver' in window)){ stage.classList.remove('is-far'); return; }
  new IntersectionObserver(function(entries){
    entries.forEach(function(e){ stage.classList.toggle('is-far', !e.isIntersecting); });
  }, { rootMargin: '150% 0px 150% 0px' }).observe(spacer);
})();
if ('IntersectionObserver' in window && exempelcaseEl && showcaseEl){
  var dueIO = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting || e.boundingClientRect.top < 0){
        warmPosters();
        mountWhenPaused(CASES[activeCaseKey]);
        dueIO.disconnect();
      }
    });
  }, { rootMargin: '0px 0px 200% 0px' }); /* R7b: due within two viewports (was one) */
  dueIO.observe(exempelcaseEl);
  var latestIO = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting || e.boundingClientRect.top < 0){
        mountCase(CASES[activeCaseKey]);
        latestIO.disconnect();
      }
    });
  }, { rootMargin: '0px 0px -40% 0px' });
  latestIO.observe(showcaseEl);
} else {
  mountCase(CASES[activeCaseKey]);
}
/* intent: a pointer over, or focus on, a case button queues its load (R7b:
   through the stillness gate, so the click that follows never waits on it) */
Array.prototype.forEach.call(document.querySelectorAll('.case-choice'), function(btn){
  function intent(){ mountWhenPaused(CASES[btn.getAttribute('data-case')]); }
  btn.addEventListener('pointerenter', intent, { once: true });
  btn.addEventListener('focus', intent, { once: true });
});

