   Tailwind's in-browser compile + first layout, CDP-traced), after ~0.45 s
   of network (each site's render-blocking Google Fonts CSS). A click that
   lands inside that task waits for all of it, so mounts are serialized: the
   next one starts only when no mounted frame is still being parsed, which
   keeps the parse window as short as the two sites allow. Still mounted at
   the reader's first pause, never during a click glide (mountCase), and a
   click cancels a mount whose parse has not begun (cancelUnparsedMounts). */
var MOUNT_QUIET_MS = 180;
var lastScrollAt = 0, pendingMounts = [], pausePoll = null;
lenis.on('scroll', function(){ lastScrollAt = performance.now(); });
function isMounted(C){ return !C.iframe.getAttribute('data-lazy-src'); }
function isParsing(C){
  if (!isMounted(C) || C.loaded) return false;
  var d = null;
  try { d = C.iframe.contentDocument; } catch (e) { return false; }
  return !d || d.URL === 'about:blank' || d.readyState === 'loading';
}
function mountWhenPaused(C){
  if (!C || isMounted(C) || pendingMounts.indexOf(C) > -1) return;
  pendingMounts.push(C);
  if (pausePoll) return;
