      var next = pendingMounts.shift();
      if (next) mountCase(next);
      pausePoll = pendingMounts.length ? setTimeout(poll, 120) : null;
      return;
    }
    pausePoll = setTimeout(poll, 120);
  })();
}
/* R7b: a site whose document has not been parsed yet would parse inside
   the glide (0.24-0.42 s tasks). The click takes it back to about:blank and
   queues it again for after the landing. A parse already running cannot be
   interrupted; the click waits for it (the one case left, see RAPPORT R7b). */
function cancelUnparsedMounts(){
  Object.keys(CASES).forEach(function(k){
    var C = CASES[k], f = C.iframe;
    if (!isParsing(C)) return;
    f.setAttribute('data-lazy-src', f.getAttribute('src'));
    f.setAttribute('src', 'about:blank');
    C.mountedAt = 0;
    afterGlide(function(){ mountWhenPaused(C); });
  });
}

