cd "/c/Users/Anton L/anti-slop-design/tests/alunix-r8" && python browser_lock.py -- python click_scroll_probe.py http://127.0.0.1:3307/tests/alunix-r8/runs/V3g/index.html --runs 4 --trace runs/V3g/shots/r7b-trace-v4-wait.json; python - <<'EOF'
import json
from collections import defaultdict
for i in (1,2,3,4):
    ev=json.load(open("runs/V3g/shots/r7b-trace-v4-wait-%d.json"%i,encoding="utf-8")); ev=ev["traceEvents"] if isinstance(ev,dict) else ev
    click=next(e["ts"] for e in ev if e.get("name")=="probe-click")
    for g in [e for e in ev if e.get("name")=="Scheduler::RunTask" and e.get("dur",0)>60000 and -100e3<e["ts"]-click<2.2e6]:
        kids=defaultdict(float); args=[]
        for e in ev:
            if e.get("ph")=="X" and e.get("pid")==g["pid"] and e.get("tid")==g["tid"] and g["ts"]<=e["ts"]<g["ts"]+g["dur"] and e is not g:
                kids[e["name"]]+=e.get("dur",0)/1000
                if e.get("dur",0)>30000 and e["name"] not in ("SkiaOutputSurfaceImplOnGpu::FinishPaintRenderPass","GrDirectContextPriv::flushSurfaces","GrDrawingManager::flush"): args.append((e["name"][:50],round(e["dur"]/1000),str(e.get("args"))[:90]))
        print(i,"GPU +%d ms %d ms:"%((g["ts"]-click)/1000,g["dur"]/1000), "; ".join("%s %.0f"%(k[:40],v) for k,v in sorted(kids.items(),key=lambda kv:-kv[1])[:7]))
        for a in args[:6]: print("      ",a)
EOF

