Object.keys(CASES).forEach(function(key){
  var C = CASES[key];
  if (!C.iframe) return;
  C.iframe.addEventListener('load', function(){
    if (isMounted(C)) afterGlide(onFrameLoad); /* not the about:blank of a cancelled mount */
  });
  /* R7b: a load that lands during a click glide (its measure is a forced
     layout of the site, 50-120 ms traced) runs once the glide has landed */
  function onFrameLoad(){
    measureCaseSettled(C);
    C.loaded = true;
    /* R7 (H1): the frame's size follows its cell, so the site re-lays out on
       resize (its own vh sections, its own triggers). Measure the anchors
       again once it has settled. */
    try {
      var t = null;
      C.iframe.contentWindow.addEventListener('resize', function(){
        clearTimeout(t);
        t = setTimeout(function(){
          measureCaseSettled(C);
          if (isPinLayout() && showcaseST && activeCaseKey === C.key) updateShowcase(C, showcaseST.progress);
        }, 350);
      });
    } catch (e) {}
    if (activeCaseKey === C.key){
      /* A#3: once loaded, the iframe fades in over 0.3s from behind its
         poster (SHOWCASE-SPEC §A) - the same duration whether this is the
         first real load or a later reload. */
      revealCase(C);
      if (isPinLayout()){
        if (showcaseST) updateShowcase(C, showcaseST.progress);
      } else {
        tweenCaseTo(C, C.pendingRow || 0);
      }
    } else {
      prewarmInactiveCase(C);
    }
  }
});
/* R7b: the first time a site is drawn, the GPU process compiles its shader
   programs: 90-500 ms per program for Hōrai (its backdrop-filter and filter
   blurs), traced as Program::MainLinkLoadEvent::wait in viz, and the whole
   page stands still meanwhile. A site that has never been drawn therefore
   never appears during a click glide: its fallback image (the same first
   screen) stands in, and the site fades in over it once the glide has
   landed (afterGlide). C.drawn marks a site that has been on screen once. */
function revealCase(C){
  if (!C.loaded || activeCaseKey !== C.key) return;
  C.iframe.style.visibility = 'visible';
  gsap.to(C.iframe, {
    opacity: 1, duration: 0.3, ease: 'power2.out', overwrite: 'auto',
    onComplete: function(){ C.drawn = true; if (C.poster) C.poster.style.display = 'none'; }
  });
}


